import {flushSync} from 'react-dom';
import {useSessionAccent} from './useSessionAccent';
import {ArrowUp} from 'lucide-react';
import {useSmoothPageScroll} from './useSmoothPageScroll';
import {useWorkspaceView} from './useWorkspaceView';
import {reloadHome} from './reloadHome.mjs';
import {SectionNavigation} from './SectionNavigation';
import {Assistant} from './features/assistant/Assistant';
import {useAssistantFlow} from './features/assistant/useAssistantFlow';
import {Catalog} from './features/catalog/Catalog';
import {ToolModal} from './ToolModal';
import {useToolNavigation} from './useToolNavigation';
import {ElasticScrollbar} from './ElasticScrollbar';
import React, {useRef, useCallback} from 'react';
export function App({useFlow=useAssistantFlow}){
 useSessionAccent();
 const navigation=useToolNavigation();
 const openRef=useRef(navigation.open);openRef.current=navigation.open;
 const openTool=useCallback((...args)=>openRef.current(...args),[]);
 const isDetail=navigation.id!==null;
 const flow=useFlow(isDetail);
 const {expanded,phase}=flow;
 const workspace=useWorkspaceView(flow.pending||Boolean(flow.error),isDetail);
 useSmoothPageScroll(isDetail);
 const resetting=useRef(false);
 async function resetArchitecture(){
  if(resetting.current)return;
  const reset=()=>{flow.newArchitecture();workspace.reset();};
  const focus=()=>flow.input.current?.focus({preventScroll:true});
  const commit=()=>{flushSync(reset);window.scrollTo({top:0,behavior:'instant'});};
  if(!document.startViewTransition||matchMedia('(prefers-reduced-motion: reduce)').matches){commit();focus();return;}
  resetting.current=true;
  const form=flow.input.current?.closest('form');
  const action=form?.parentElement.querySelector('.composer-new-architecture');
  let centerMotion,buttonMotion;
  if(form&&action){
   const bounds=form.getBoundingClientRect();
   const width=Math.min(756,document.documentElement.clientWidth-(innerWidth<=640?24:48));
   const left=(document.documentElement.clientWidth-width)/2;
   centerMotion=form.animate([
    {translate:'0px 0px',width:`${bounds.width}px`,marginRight:'0px',flex:'none'},
    {translate:`${left-bounds.left}px 0px`,width:`${width}px`,marginRight:`${bounds.width-width}px`,flex:'none'}
   ],{duration:220,easing:'cubic-bezier(.22,1,.36,1)',fill:'forwards'});
   buttonMotion=action.animate([{opacity:1},{opacity:0}],{duration:140,fill:'forwards'});
   await centerMotion.finished.catch(()=>{});
  }
  document.documentElement.dataset.architectureReset='true';
  const transition=document.startViewTransition(()=>{centerMotion?.cancel();buttonMotion?.cancel();commit();});
  transition.finished.catch(()=>{}).finally(()=>{
   delete document.documentElement.dataset.architectureReset;
   resetting.current=false;
   focus();
  });
 }

 return <><a href="#asistente" className="skip" inert={isDetail?true:undefined}>Ir al contenido</a><header inert={isDetail?true:undefined} aria-hidden={isDetail}><div className="nav wrap"><a className="brand" href="/" onClick={reloadHome}><img className="openbridge-logo" src="/assets/brands/openbridge.svg" alt="OpenBridge"/></a><SectionNavigation paused={isDetail} workspace={workspace}/></div></header>
 <main inert={isDetail?true:undefined} aria-hidden={isDetail} id="landing-view" data-has-proposal={expanded} data-surface-mode={workspace.mode}><div ref={workspace.assistantRef} className="assistant-surface" inert={workspace.covered?true:undefined}><Assistant flow={{...flow,newArchitecture:resetArchitecture}} workspace={workspace.active}/></div>
 <div ref={workspace.catalogRef} hidden={workspace.mode==='locked'} className="catalog-surface"><Catalog onOpen={openTool} phase={phase}/></div>{workspace.offer&&!isDetail&&<button ref={workspace.buttonRef} type="button" className="ui-button ui-button--primary catalog-access" onClick={()=>workspace.openCatalog()}><span>Ver catálogo</span><ArrowUp size={16} aria-hidden="true"/></button>}</main>{isDetail&&<ToolModal id={navigation.id} onClose={navigation.back}/>}<ElasticScrollbar/></>;
}

import {useBrandIdentity,markBrandFailed} from './brandIdentity';
export function BrandIcon({tool}){
 const identity=useBrandIdentity(tool);
 return identity.fallback?<span className="brand-initials" aria-hidden="true">{identity.initials}</span>:<img src={identity.logo} alt="" onError={()=>markBrandFailed(identity.logo)}/>;
}

"use client";
import {useTypingProbe} from './debug/useTypingProbe';
import {App} from './App';
import {CatalogProvider} from './data/CatalogProvider';
// Keep the existing browser-only animation boot and hash routes intact.
if(typeof window!=='undefined'){
 window.history.scrollRestoration='manual';
 if(!location.hash.startsWith('#herramienta/'))history.replaceState(history.state,'',`${location.pathname}${location.search}#asistente`);
 window.scrollTo({top:0,left:0,behavior:'instant'});
}
export default function ClientApp(){useTypingProbe();return <div id="root" data-reveal-boot=""><CatalogProvider><App/></CatalogProvider></div>;}

// Fixed geometry keeps the expression readable throughout the light sweep.
const dots=[];
for(const center of [112,208]){
 for(let y=98;y<=142;y+=7){
  for(let x=center-12;x<=center+12;x+=6){
   if(((x-center)/13)**2+((y-120)/25)**2<=1)dots.push({x,y});
  }
 }
}
for(let row=-1;row<=1;row++){
 for(let step=0;step<=26;step++){
  const x=96+step*128/26;
  const y=180+34*((x-160)/64)**2+row*6;
  if(row===0||step>0&&step<26)dots.push({x,y});
 }
}
const dizzyDots=[];
for(const center of [112,208]){
 for(let angle=0;angle<=Math.PI*4;){
  const radius=3+angle*1.65;
  dizzyDots.push({x:center+Math.cos(angle)*radius,y:122+Math.sin(angle)*radius});
  angle+=5.4/Math.hypot(radius,1.65);
 }
}
dizzyDots.push(...dots.filter(dot=>dot.y>=170));
export function DotSadFace({variant='sad'}){
 const points=variant==='dizzy'?dizzyDots:dots;
 return <svg className="catalog-error-face dot-sad-face" viewBox="0 0 320 320" width="320" height="320" aria-hidden="true" focusable="false">
  <g fill="#b9cadb" opacity=".32">{points.map((dot,i)=><circle key={i} cx={dot.x} cy={dot.y} r="1.8"/>)}</g>
  <g className="dot-face-light">{points.map((dot,i)=><circle key={i} cx={dot.x} cy={dot.y} r="1.8" style={{animationDelay:`${-6+(dot.x-84)/160*1.8+(dot.y-96)/128*.65}s`}}/>)}</g>
 </svg>;
}

// A compact dotted question mark shares the faces' restrained light sweep.
const questionRows=[
 '  XXXXX  ',
 ' XXXXXXX ',
 'XX     XX',
 'XX     XX',
 '       XX',
 '      XX ',
 '     XX  ',
 '    XX   ',
 '    XX   ',
 '         ',
 '    XX   ',
 '    XX   ',
];
const questionDots=questionRows.flatMap((row,y)=>Array.from(row,(cell,x)=>cell==='X'?{x:8+x*5,y:6+y*5}:null).filter(Boolean));
export function DotQuestion({index=0}){
 return <svg className="clarification-symbol" viewBox="0 0 56 68" width="56" height="68" aria-hidden="true" focusable="false">
  <g fill="#b9cadb" opacity=".4">{questionDots.map((dot,i)=><circle key={i} cx={dot.x} cy={dot.y} r="1.5"/>)}</g>
  <g className="dot-face-light">{questionDots.map((dot,i)=><circle key={i} cx={dot.x} cy={dot.y} r="1.5" style={{animationDelay:`${-6+dot.x/56*1.8+dot.y/68*.65-index*.7}s`}}/>)}</g>
 </svg>;
}

import {memo,useEffect,useRef} from 'react';
import {borderLightFrame} from './promptBorderGeometry.mjs';

export const ElasticPromptBorder=memo(function ElasticPromptBorder(){
 const root=useRef(null);
 useEffect(()=>{
  const svg=root.current,form=svg.parentElement;
  const paths=svg.querySelectorAll(':scope > path'),light=svg.querySelector('radialGradient');
  const reduced=matchMedia('(prefers-reduced-motion: reduce)'),fine=matchMedia('(hover: hover) and (pointer: fine)');
  let rect,buttonBox,points=[],raf=0,last=0,disposed=false;
  let burstStart=null,releasing=false,side=0,sideX=0;
  let glowFrame=null,glowSettling=false;
  let x=0,y=0,tx=0,ty=0,strength=0,target=0,cx=0,cy=0;
  function paint(now=performance.now()){
   form.style.setProperty('--prompt-glare-x',`${cx}px`);
   form.style.setProperty('--prompt-glare-y',`${cy}px`);
   form.style.setProperty('--prompt-glare-opacity',form.contains(document.activeElement)?0:strength);
   form.style.removeProperty('translate');
   if(buttonBox){
    const bx=cx-buttonBox.x,by=cy-buttonBox.y;
    const distance=Math.hypot(bx-buttonBox.width/2,by-buttonBox.height/2);
    const reflection=form.contains(document.activeElement)?0:strength*Math.exp(-(distance*distance)/(2*150*150));
    form.style.setProperty('--submit-reflection',String(reflection*.18));
    form.style.setProperty('--submit-reflection-x',`${bx}px`);
    form.style.setProperty('--submit-reflection-y',`${by}px`);
   }
   const d=points.map(([px,py,nx,ny],i)=>{
    const pull=0;
    return `${i?'L':'M'}${(px+nx*pull).toFixed(2)},${(py+ny*pull).toFixed(2)}`;
   }).join(' ')+' Z';
   paths.forEach(path=>path.setAttribute('d',d));
   light.setAttribute('cx',cx);light.setAttribute('cy',cy);
   const hoverRadius=Math.min(85,rect.height*.4,rect.width*.22);
   if(burstStart!==null){
    light.removeAttribute('gradientTransform');
    const progress=Math.min(1,(now-burstStart)/(releasing?950:720));
    const spread=releasing?1:1-(1-progress)**3;
    light.setAttribute('r',hoverRadius+(Math.hypot(rect.width,rect.height)*1.3-hoverRadius)*spread);
    paths[1].style.opacity=String(releasing?1-progress*progress*(3-2*progress):1-Math.max(0,(progress-.5)/.5)**2);
    if(progress===1){burstStart=null;releasing=false;}
   }else{
    light.setAttribute('r',hoverRadius);
    const {x:gx,y:gy,angle}=glowFrame||borderLightFrame(cx,cy,rect.width,rect.height);
    const stretch=280/hoverRadius;
    light.setAttribute('cx',gx);light.setAttribute('cy',gy);
    light.setAttribute('gradientTransform',`translate(${gx} ${gy}) rotate(${angle}) scale(${stretch} 1) translate(${-gx} ${-gy})`);
    paths[1].style.opacity=String(strength);
   }
   const fade=svg.querySelector('#prompt-reflection-fade');
   const magnitude=Math.min(1,Math.hypot(sideX,side));
   const norm=Math.hypot(sideX,side)||1;
   const dx=sideX/norm,dy=side/norm;
   const extent=Math.abs(dx)*rect.width/2+Math.abs(dy)*rect.height/2;
   fade.setAttribute('x1',rect.width/2);fade.setAttribute('y1',rect.height/2);
   fade.setAttribute('x2',rect.width/2+dx*extent);fade.setAttribute('y2',rect.height/2+dy*extent);
   const bright=Math.round(magnitude*255);
   fade.lastElementChild.setAttribute('stop-color',`rgb(${bright} ${bright} ${bright})`);
   paths[2].style.opacity=String(Number(paths[1].style.opacity)*.28);
   paths[3].style.opacity=String(Number(paths[1].style.opacity)*.16);
  }
  function tick(now){
   raf=0;if(disposed)return;
   const dt=Math.min(now-(last||now-16),40);last=now;
   const k=1-Math.exp(-dt/95);
   const goal=borderLightFrame(cx,cy,rect.width,rect.height);
   if(!glowFrame||strength<.005)glowFrame={...goal};
   const turn=((goal.angle-glowFrame.angle+540)%360)-180;
   const follow=1-Math.exp(-dt/140);
   glowFrame.x+=(goal.x-glowFrame.x)*follow;
   glowFrame.y+=(goal.y-glowFrame.y)*follow;
   glowFrame.angle=(glowFrame.angle+turn*follow+360)%360;
   glowSettling=Math.hypot(goal.x-glowFrame.x,goal.y-glowFrame.y)>.1||Math.abs(turn)>.1;

   const targetSide=rect?Math.max(-1,Math.min(1,(cy/rect.height-.5)*4)):0;
   const targetX=rect?Math.max(-1,Math.min(1,(cx/rect.width-.5)*4)):0;
   side+=(targetSide-side)*k;sideX+=(targetX-sideX)*k;
   x+=(tx-x)*k;y+=(ty-y)*k;strength+=(target-strength)*k;
   paint(now);
   if(glowSettling||burstStart!==null||Math.abs(targetX-sideX)+Math.abs(targetSide-side)+Math.abs(tx-x)+Math.abs(ty-y)+Math.abs(target-strength)>.003)raf=requestAnimationFrame(tick);else last=0;
  }
  function start(){if(!raf)raf=requestAnimationFrame(tick);}
  function reset(){tx=ty=target=0;start();}
  function measure(){
   const box=form.getBoundingClientRect();rect={left:box.left-x,top:box.top-y,width:box.width,height:box.height};
   const button=form.querySelector('.prompt-submit')?.getBoundingClientRect();
   buttonBox=button?{x:button.left-box.left,y:button.top-box.top,width:button.width,height:button.height}:null;
   const w=box.width,h=box.height,r=12;points=[];
   // Clockwise rounded contour; outward normals deform only the nearby edge.
   const corners=[[w-r,r,-90],[w-r,h-r,0],[r,h-r,90],[r,r,180]];
   corners.forEach(([ox,oy,angle],index)=>{
    for(let a=0;a<=90;a+=9){const t=(angle+a)*Math.PI/180;points.push([ox+r*Math.cos(t),oy+r*Math.sin(t),Math.cos(t),Math.sin(t)]);}
    const next=corners[(index+1)%4],t=(angle+90)*Math.PI/180;
    const ax=ox+r*Math.cos(t),ay=oy+r*Math.sin(t),bx=next[0]+r*Math.cos(t),by=next[1]+r*Math.sin(t);
    const steps=Math.ceil(Math.hypot(bx-ax,by-ay)/10);
    for(let i=1;i<steps;i++)points.push([ax+(bx-ax)*i/steps,ay+(by-ay)*i/steps,Math.cos(t),Math.sin(t)]);
   });
   svg.querySelector('#prompt-reflection-fade').setAttribute('y1',0);
   svg.querySelector('#prompt-reflection-fade').setAttribute('y2',h);
   svg.querySelector('#prompt-reflection-mask').setAttribute('width',w+256);
   svg.querySelector('#prompt-reflection-mask').setAttribute('height',h+256);
   svg.querySelector('#prompt-reflection-mask rect').setAttribute('width',w+256);
   svg.querySelector('#prompt-reflection-mask rect').setAttribute('height',h+256);
   svg.querySelector('clipPath path').setAttribute('d',`M-128 -128H${w+128}V${h+128}H-128Z M12 0H${w-12}Q${w} 0 ${w} 12V${h-12}Q${w} ${h} ${w-12} ${h}H12Q0 ${h} 0 ${h-12}V12Q0 0 12 0Z`);
   svg.setAttribute('viewBox',`-128 -128 ${w+256} ${h+256}`);paint();
  }
  function move(e){
   if(releasing||form.contains(document.activeElement)||e.pointerType==='touch'||reduced.matches||!fine.matches||document.hidden)return;
   if(!rect)return;
   cx=e.clientX-rect.left;cy=e.clientY-rect.top;
   const outside=Math.hypot(Math.max(0,-cx,cx-rect.width),Math.max(0,-cy,cy-rect.height));
   target=Math.max(0,1-outside/90);
   tx=0;
   ty=0;
   start();
  }
  const observer=new ResizeObserver(measure);observer.observe(form);measure();
  document.addEventListener('pointermove',move,{passive:true});document.addEventListener('pointerleave',reset);
  window.addEventListener('scroll',measure,{passive:true});window.addEventListener('blur',reset);
  function stop(){releasing=false;glowFrame=null;glowSettling=false;burstStart=null;cancelAnimationFrame(raf);raf=0;last=0;x=y=tx=ty=strength=target=0;paint();}
  function activate(){
   if(reduced.matches||document.hidden){stop();return;}
   releasing=false;tx=ty=target=0;burstStart=performance.now();start();
  }
  function press(e){
   if(e.target.tagName!=='TEXTAREA')return;
   if(rect){cx=e.clientX-rect.left;cy=e.clientY-rect.top;}
   if(!form.contains(document.activeElement))return;
  }
  function focus(e){if(!form.contains(e.relatedTarget))activate();}
  function blur(e){if(!form.contains(e.relatedTarget))stop();}
  form.addEventListener('pointerdown',press);form.addEventListener('focusin',focus);form.addEventListener('focusout',blur);
  document.addEventListener('visibilitychange',stop);reduced.addEventListener('change',stop);
  return()=>{disposed=true;cancelAnimationFrame(raf);observer.disconnect();form.removeEventListener('pointerdown',press);form.removeEventListener('focusin',focus);form.removeEventListener('focusout',blur);form.style.removeProperty('translate');['--prompt-glare-x','--prompt-glare-y','--prompt-glare-opacity','--submit-reflection','--submit-reflection-x','--submit-reflection-y'].forEach(key=>form.style.removeProperty(key));document.removeEventListener('pointermove',move);document.removeEventListener('pointerleave',reset);window.removeEventListener('scroll',measure);window.removeEventListener('blur',reset);document.removeEventListener('visibilitychange',stop);reduced.removeEventListener('change',stop);};
 },[]);
 return <svg ref={root} className="elastic-prompt-border" aria-hidden="true"><defs><linearGradient id="prompt-background-light" x1="50%" y1="0%" x2="50%" y2="100%"><stop stopColor="var(--prompt-light-color, #ffffff)" stopOpacity=".6"/><stop offset="1" stopColor="var(--prompt-light-color, #ffffff)" stopOpacity=".15"/></linearGradient><radialGradient id="prompt-edge-light" gradientUnits="userSpaceOnUse" r="85"><stop stopColor="#ffffff"/><stop offset=".14" stopColor="var(--prompt-light-core, #ffffff)"/><stop offset=".30" stopColor="var(--prompt-light-fringe-cool, #edfaff)" stopOpacity=".85"/><stop offset=".62" stopColor="var(--prompt-light-fringe-soft, #f0edff)" stopOpacity=".45"/><stop offset=".84" stopColor="var(--prompt-light-color, #ffffff)" stopOpacity=".15"/><stop offset="1" stopColor="var(--prompt-light-color, #ffffff)" stopOpacity="0"/></radialGradient><radialGradient id="prompt-edge-spill" href="#prompt-edge-light"><stop stopColor="var(--prompt-spill-cool, #8cdff5)" stopOpacity=".85"/><stop offset=".48" stopColor="var(--prompt-spill-cool, #8cdff5)" stopOpacity=".7"/><stop offset=".76" stopColor="var(--prompt-spill-rose, #e8a9d5)" stopOpacity=".6"/><stop offset="1" stopColor="var(--prompt-spill-rose, #e8a9d5)" stopOpacity="0"/></radialGradient><clipPath id="prompt-foil-exterior" clipPathUnits="userSpaceOnUse"><path clipRule="evenodd"/></clipPath><linearGradient id="prompt-reflection-fade" gradientUnits="userSpaceOnUse" x1="0" x2="0"><stop stopColor="black"/><stop offset=".35" stopColor="black"/><stop offset="1" stopColor="black"/></linearGradient><mask id="prompt-reflection-mask" maskUnits="userSpaceOnUse" x="-128" y="-128" width="100%" height="100%"><rect x="-128" y="-128" fill="url(#prompt-reflection-fade)"/></mask></defs><path className="elastic-edge-base"/><path className="elastic-edge-light" stroke="url(#prompt-edge-light)"/><path className="elastic-edge-reflection" mask="url(#prompt-reflection-mask)" stroke="url(#prompt-edge-spill)" clipPath="url(#prompt-foil-exterior)"/><path className="elastic-edge-reflection elastic-edge-ambient" mask="url(#prompt-reflection-mask)" stroke="url(#prompt-edge-spill)" clipPath="url(#prompt-foil-exterior)"/><path className="elastic-edge-focus"/></svg>;
});

import {useLayoutEffect,useRef} from 'react';
import {scrollbarMetrics,elasticThumb,followScroll,scrollFromThumb,updateScrollGesture,gestureStretch} from './scrollbarGeometry.mjs';

export function ElasticScrollbar(){
 const railRef=useRef(null),thumbRef=useRef(null);
 useLayoutEffect(()=>{
  const rail=railRef.current,thumb=thumbRef.current,root=document.documentElement;
  const eligible=matchMedia('(min-width:768px) and (pointer:fine) and (hover:hover) and (prefers-reduced-motion:no-preference) and (forced-colors:none)');
  let metrics,enabled=false,drag=null,raf=0,idle=0,last=0,trailing=0,snapUntil=performance.now()+800,disposed=false;
  let gesture={distance:0,direction:0,time:-Infinity},stretch=0,lastY=scrollY;
  const originalPadding=root.style.paddingRight;
  function resetGesture(){gesture={distance:0,direction:0,time:-Infinity};stretch=0;lastY=scrollY;}
  function active(){rail.dataset.active='true';clearTimeout(idle);idle=setTimeout(()=>{rail.dataset.active='false';},800);}
  function paint(){
   const shape=elasticThumb(metrics,metrics.position,drag?0:stretch);
   thumb.style.transform=`translateY(${shape.top}px) scaleY(${shape.length})`;
   thumb.style.borderRadius=`3px / ${3/shape.length}px`;
   rail.setAttribute('aria-valuemax',String(Math.round(metrics.maxScroll)));
   rail.setAttribute('aria-valuenow',String(Math.round(Math.max(0,Math.min(scrollY,metrics.maxScroll)))));
   rail.setAttribute('aria-valuetext',`${Math.round(metrics.maxScroll?Math.max(0,Math.min(1,scrollY/metrics.maxScroll))*100:0)} %`);
  }
  function stop(){cancelAnimationFrame(raf);raf=0;last=0;}
  function tick(now){
   raf=0;if(!enabled||document.hidden||disposed)return;
   metrics=scrollbarMetrics(innerHeight,root.scrollHeight,scrollY);
   trailing=drag||now<snapUntil?metrics.position:followScroll(trailing,metrics.position,last?Math.min(now-last,64):16);
   const target=!drag&&now>=snapUntil&&now-gesture.time<120?gesture.direction*gestureStretch(metrics,gesture.distance):0;
   const dt=last?Math.min(now-last,64):16;
   stretch=target+(stretch-target)*Math.exp(-dt/(target===0?80:45));
   if(Math.abs(stretch-target)<.05)stretch=target;
   last=now;
   if(Math.abs(trailing-metrics.position)<.05)trailing=metrics.position;
   paint();
   if(trailing!==metrics.position||stretch!==0||target!==0)raf=requestAnimationFrame(tick);else last=0;
  }
  function schedule(){if(!raf&&!document.hidden)raf=requestAnimationFrame(tick);}
  function measure(snap=true){
   metrics=scrollbarMetrics(innerHeight,root.scrollHeight,scrollY);
   const next=eligible.matches&&metrics.maxScroll>1&&metrics.travel>0;
   if(next!==enabled){
    enabled=next;
    if(enabled){
     // Replace the occupied native gutter without changing the content width.
     const gutter=Math.max(0,innerWidth-root.clientWidth);
     root.style.paddingRight=`${parseFloat(getComputedStyle(root).paddingRight)+gutter}px`;
     root.classList.add('elastic-scrollbar-active');
    }else{
     root.classList.remove('elastic-scrollbar-active');root.style.paddingRight=originalPadding;
     if(drag){if(rail.hasPointerCapture(drag.id))rail.releasePointerCapture(drag.id);drag=null;}
     stop();
    }
    rail.hidden=!enabled;
   }
   if(!enabled)return;
   if(snap){trailing=metrics.position;resetGesture();}
   paint();schedule();
  }
  function onScroll(){if(!enabled)return;const now=performance.now(),y=Math.max(0,Math.min(scrollY,metrics.maxScroll));
   if(!drag&&now>=snapUntil)gesture=updateScrollGesture(gesture,y-lastY,now);
   lastY=y;active();schedule();}
  function jump(position){window.scrollTo({top:scrollFromThumb(metrics,position),behavior:'instant'});metrics=scrollbarMetrics(innerHeight,root.scrollHeight,scrollY);trailing=metrics.position;resetGesture();paint();active();}
  function down(event){
   if(!enabled||event.button!==0)return;
   event.preventDefault();rail.focus({preventScroll:true});measure(false);
   const y=event.clientY-metrics.inset;
   const shape=elasticThumb(metrics,metrics.position,stretch);
   const inThumb=event.clientY>=shape.top&&event.clientY<=shape.top+shape.length;
   // Preserve the exact grabbed point when removing any elastic stretch.
   const offset=inThumb?(event.clientY-shape.top)/shape.length*metrics.length:metrics.length/2;
   drag={id:event.pointerId,offset};rail.setPointerCapture(event.pointerId);rail.dataset.dragging='true';
   jump(y-offset);
  }
  function move(event){if(drag?.id===event.pointerId)jump(event.clientY-metrics.inset-drag.offset);}
  function end(event){if(drag?.id!==event.pointerId)return;const id=drag.id;drag=null;rail.dataset.dragging='false';if(rail.hasPointerCapture(id))rail.releasePointerCapture(id);active();measure();}
  function key(event){
   if(!enabled)return;
   const targets={ArrowDown:scrollY+40,ArrowUp:scrollY-40,PageDown:scrollY+innerHeight*.9,PageUp:scrollY-innerHeight*.9,Home:0,End:metrics.maxScroll};
   if(!(event.key in targets))return;event.preventDefault();window.scrollTo({top:targets[event.key],behavior:'instant'});onScroll();
  }
