     <path className="elk-wire-base" d={path}/>
     <defs><mask id={maskId} maskUnits="userSpaceOnUse" x="-12" y="-12" width={layout.width+24} height={layout.height+24}>
      <g filter={`url(#${lightId}-soft-light)`}>
