   </FollowingTooltip></div>;})}
   {failed&&connections.map((c,i)=><p key={i}>{components.find(n=>n.key===c.from_key)?.label} → {components.find(n=>n.key===c.to_key)?.label}{c.protocol?` · ${c.protocol}`:''}{c.description?`: ${c.description}`:''}</p>)}
  </div>
  </div>
